import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceExpireStaleTest {

    private static final Instant NOW = Instant.parse("2026-10-31T12:00:00Z");

    private final OrderRepository repository = new OrderRepository();
    private final Clock clock = Clock.fixed(NOW, ZoneOffset.UTC);
    private final OrderService service = new OrderService(repository, clock);

    @Test
    void cancelsOnlyPlacedOrdersOlderThanThirtyDays() {
        String old = place(NOW.minusSeconds(31L * 24 * 3600));
        String edge = place(NOW.minusSeconds(30L * 24 * 3600));
        String recent = place(NOW.minusSeconds(29L * 24 * 3600));
        String oldConfirmed = place(NOW.minusSeconds(60L * 24 * 3600));
        service.confirm(oldConfirmed);

        int cancelled = service.expireStale();

        assertEquals(1, cancelled);
        assertEquals("CANCELLED", service.summary(old).status());
        assertEquals("PLACED", service.summary(edge).status());
        assertEquals("PLACED", service.summary(recent).status());
        assertEquals("CONFIRMED", service.summary(oldConfirmed).status());
    }

    @Test
    void returnsZeroWhenNothingIsStale() {
        place(NOW.minusSeconds(60));

        assertEquals(0, service.expireStale());
    }

    @Test
    void secondRunCancelsNothingMore() {
        place(NOW.minusSeconds(40L * 24 * 3600));

        assertEquals(1, service.expireStale());
        assertEquals(0, service.expireStale());
    }

    private String place(Instant placedAt) {
        return service.place("c-1", Money.pln(1000), placedAt);
    }
}
}
